async function customerSession(admin:SupabaseClient,station:any,token:string,{touch=true}={}){if(!token)throw Object.assign(new Error('Member sign-in required.'),{status:401,code:'AUTH_REQUIRED'});const tokenHash=await sha256(token);const{data,error}=await admin.from('branch_customer_auth_sessions').select('*').eq('token_hash',tokenHash).eq('branch_id',station.branch_id).eq('station_device_id',station.id).is('revoked_at',null).gt('expires_at',new Date().toISOString()).maybeSingle();if(error)throw error;if(!data)throw Object.assign(new Error('Customer session expired. Sign in again.'),{status:401,code:'AUTH_INVALID'});const{data:member,error:memberError}=await admin.from('branch_members').select('*').eq('branch_id',station.branch_id).eq('local_id',data.member_id).eq('status','active').maybeSingle();if(memberError)throw memberError;if(!member)throw Object.assign(new Error('Member account is inactive.'),{status:403,code:'ACCOUNT_INACTIVE'});const{data:cred}=await admin.from('branch_member_credentials').select('must_change_credentials').eq('branch_id',station.branch_id).eq('member_id',data.member_id).maybeSingle();if(touch)await admin.from('branch_customer_auth_sessions').update({last_seen_at:new Date().toISOString(),expires_at:new Date(Date.now()+12*60*60*1000).toISOString()}).eq('token_hash',tokenHash);return{auth:data,member,user:memberView(member,station,Boolean(cred?.must_change_credentials)),tokenHash}}
