  if(method==='POST'&&base==='/sessions/start'){const auth=await customerSession(admin,station,localAuthToken);const{data:pcState,error:pcStateError}=await admin.from('branch_stations').select('status').eq('branch_id',station.branch_id).eq('local_id',station.local_station_id).maybeSingle();if(pcStateError)throw pcStateError;if(String(pcState?.status||'available').toLowerCase()==='maintenance')throw Object.assign(new Error('This PC is in maintenance mode.'),{status:409,code:'PC_MAINTENANCE'});const out=await cloudExecute(admin,station,'session.start',{...requestBody,pcId:station.local_station_id,customerId:auth.member.local_id,customerName:auth.member.name,billing:'prepaid'},'member',auth.member.local_id,operationKey);return json(out,Number(out.status||201))}
